cd /workspace && python3 - <<'EOF'
import json, sys, math
print(sys.get_int_max_str_digits())
# long int token
for n in (4300, 4301):
    s = '{"a":' + '9'*n + '}'
    try:
        json.loads(s); print(n, 'ok')
    except Exception as e: print(n, type(e).__name__, str(e)[:80])
# float long digits
s='{"a":' + '9'*5000 + '.0}'
try:
    json.loads(s); print('float long ok')
except Exception as e: print('float long', type(e).__name__, str(e)[:100])
# deep nesting
s='['*200000 + ']'*200000
try:
    json.loads(s); print('deep ok')
except Exception as e: print('deep', type(e).__name__, str(e)[:100])
# overflow float token
try:
    print(json.loads('{"a":1e400}', parse_float=lambda t: float(t)))
except Exception as e: print('overflow', type(e).__name__, e)
print(float('1e-400'))
# BOM
try:
    json.loads('\ufeff{}')
except Exception as e: print('bom', type(e).__name__, str(e)[:60])
EOF
